INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch08$PT156-S2-Q14$batch08$, 156, 2, 14, $batch08$Most Strongly Supported$batch08$, $batch08$When polar ice caps grow (during ice ages, for example), lighter forms of oxygen from water vapor and seawater accumulate in the frozen ice caps, leaving greater concentrations of one heavy form of oxygen behind in the sea, where it is absorbed by marine organisms. When and as the ice caps shrink, the concentrations of this heavy oxygen in seawater decrease. During one 30,000- year period, concentrations of this heavy oxygen in sea shellfish increased for about 20,000 years, then decreased for 10,000 years.$batch08$, $batch08$The information given most strongly supports which one of the following hypotheses about the period described above?$batch08$, $batch08$D$batch08$, true, $batch08$Batch 08; question text from local bank.$batch08$ FROM lr_sections s WHERE s.preptest=156 AND s.section=2 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch08$PT156-S2-Q14$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$A$batch08$, $batch08$Average global temperatures 10,000 years after the beginning of the period approximately equaled average global temperatures 20,000 years later.$batch08$, $batch08$Out of Scope$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT156-S2-Q14$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$A$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$B$batch08$, $batch08$Polar ice caps at the beginning of the period were larger than they were at the end of the period.$batch08$, $batch08$Unsupported$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT156-S2-Q14$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$B$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$C$batch08$, $batch08$The beginning of the period coincided with the onset of an ice age that lasted approximately 20,000 years.$batch08$, $batch08$Too Strong$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT156-S2-Q14$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$C$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$D$batch08$, $batch08$The polar ice caps grew for about 20,000 years after the period began, then began to shrink.$batch08$, $batch08$Correct$batch08$, true FROM lr_questions q WHERE q.qid=$batch08$PT156-S2-Q14$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$D$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$E$batch08$, $batch08$An ice age was drawing to an end during the first 20,000 years of the period.$batch08$, $batch08$Opposite$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT156-S2-Q14$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$E$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch08$PT156-S2-Q14$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch08$Statements$batch08$, $batch08$When ice caps grow, light oxygen gets locked in the ice and heavy oxygen builds up in the sea, where shellfish absorb it. When caps shrink, heavy oxygen in seawater falls. Over one 30,000-year period, heavy oxygen in shellfish rose for about 20,000 years, then fell for 10,000.$batch08$), (1, $batch08$Evaluate$batch08$, $batch08$Pause and infer by running the rule backward. Heavy oxygen rising means the caps were growing. Heavy oxygen falling means they were shrinking. So: about 20,000 years of growth, then 10,000 of shrinking.$batch08$), (2, $batch08$Goal$batch08$, $batch08$The ice caps grew for about 20,000 years, then shrank.$batch08$)) v(position,label,body) WHERE q.qid=$batch08$PT156-S2-Q14$batch08$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch08$A$batch08$, $batch08$The passage links oxygen to ice caps, not to temperature figures.$batch08$), ($batch08$B$batch08$, $batch08$Twenty thousand years of growth followed by ten thousand of shrinking doesn't tell us the net. The caps could have ended up bigger, smaller, or the same.$batch08$), ($batch08$C$batch08$, $batch08$The caps grew, but whether an ice age began right at the start of the period is more than the data shows.$batch08$), ($batch08$D$batch08$, $batch08$It is the oxygen record translated back into ice: up for about 20,000 years, then down.$batch08$), ($batch08$E$batch08$, $batch08$During the first 20,000 years the caps were growing, not shrinking.$batch08$)) v(letter,body) WHERE q.qid=$batch08$PT156-S2-Q14$batch08$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
